#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <queue>
#include <set>
#include <map>
#include <stack>
using namespace std;

typedef long long LL;
const int MAX_SIZE=250100;

int readNumber() {
    int val=0; bool sign=true; char c=getchar();
    while ((c<'0'||c>'9') && c!='-') c=getchar();
    if (c=='-') { sign=false; c=getchar(); }
    while (c>='0' && c<='9') { val=val*10+c-'0'; c=getchar(); }
    return sign ? val : -val;
}

int MOD, mCount;
int sizeArr[MAX_SIZE], invArr[MAX_SIZE];
struct DataType { int a[19]; } arrayData[MAX_SIZE];

inline int fastExponentiation(int base, int exponent) {
    int result=1;
    while (exponent) {
        if (exponent & 1) result=1LL*result*base%MOD;
        base=1LL*base*base%MOD; exponent>>=1;
    }
    return result;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("CF838C.in","r",stdin);
    freopen("CF838C.out","w",stdout);
#endif
    int i, s, n=readNumber(), k=readNumber(), a, b, y, t[20]={}, p[20]={};
    DataType *F, *G;
    MOD=readNumber();

    if (n%2==1) {
        printf("%d\n", fastExponentiation(k, n));
        return 0;
    }

    for (i=0; i<18; i++) mCount+= (n>>i)&1;

    for (i=0, s=1; i<=n; i++) {
        invArr[i]=i<2 ? 1 : -1LL*(MOD/i)*invArr[MOD%i]%MOD;
        sizeArr[i]=sizeArr[i>>1]+(i&1);
        s=1LL*s*invArr[i]%MOD;
        if ((i&n)==i)
            arrayData[i].a[sizeArr[i]]=s;
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&arrayData[s^(1<<i)], G=&arrayData[s]; a<=mCount; a++) (G->a[a]+=F->a[a])%=MOD;

    for (i=0; i<=n; i++) if ((i&n)==i) {
        F=&arrayData[i];
        for (a=0; a<=mCount; a++) y[a]=F->a[a], F->a[a]=!a;
        for (b=k; b; b>>=1) {
            if (b&1) {
                for (a=0; a<=mCount; a++) p[a]=F->a[a], F->a[a]=0;
                for (a=0; a<=mCount; a++)
                    if (y[a])
                        for (b=0; a+b<=mCount; b++)
                            F->a[a+b]=(F->a[a+b]+1LL*y[a]*p[b])%MOD;
            }
            if (b>>=1) {
                for (a=0; a<=mCount; a++) p[a]=y[a], y[a]=0;
                for (a=0; a<=mCount; a++)
                    if (p[a])
                        for (b=0; a+b<=mCount; b++)
                            y[a+b]=(y[a+b]+1LL*p[a]*p[b])%MOD;
            }
        }
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&arrayData[s^(1<<i)], G=&arrayData[s]; a<=mCount; a++) (G->a[a]-=F->a[a])%=MOD;

    y=arrayData[n].a[mCount];
    for (i=n; i; i--) y=1LL*y*i%MOD;
    printf("%d\n", ((fastExponentiation(k, n)-y)%MOD+MOD)%MOD);
    return 0;
}
